customCSS:
.t, .history { color: #707880; }
.join { color: #b5bd68; }
.part, .quit { color: #707880; }
.kick, .error { color: #cc6666; }
.notice { color: #f0c674; }
.action { color: #b294bb; }
.mode, .nick, .topic, .server { color: #8abeb7; }
.highlight { color: #c5c8c6; background-color: #373b41; border-left: 3px solid #b294bb; padding-left: 8px; }
.reply { color: #707880; border-left: 2px solid #81a2be; padding-left: 6px; }
.oper { color: #1d1f21; background-color: #f0c674; }
.reactions { color: #81a2be; background-color: #282a2e; }
.card { background-color: #282a2e; border-color: #707880; }
.card-title { color: #81a2be; }
.card-desc { color: #707880; }
.daychange { color: #707880; border-color: #282a2e; }
